// Email brand art (spec 0010 AC-6): the drawn lockup for the header and the
// reduced mark for the footer. Geometry comes from src/lib/brand-art.ts,
// generated by pnpm brand:lockup; colors interpolate BRAND palette constants
// because email clients need inline hex and check:hex bans literals here.

import {
  LOCKUP_CHIP,
  LOCKUP_GLYPHS,
  PRIMARY_CHIP,
  REDUCED_CHIP,
} from "@/lib/brand-art"

type Colors = {
  chip: string
  dots: string
  keeper: string
  word: string
}

/** 736x160 art; render at width 180 to match the 40px chip height. */
export function EmailLockup({
  colors,
  width,
}: {
  colors: Colors
  width: number
}) {
  return (
    <svg
      width={width}
      height={(width * 160) / 736}
      viewBox="0 0 736 160"
      role="img"
      aria-label="Payday Pitch"
      style={{ display: "block" }}
    >
      <g
        transform={`translate(${LOCKUP_CHIP.x} ${LOCKUP_CHIP.y}) scale(${LOCKUP_CHIP.scale})`}
      >
        <rect
          width={PRIMARY_CHIP.size}
          height={PRIMARY_CHIP.size}
          rx={PRIMARY_CHIP.rx}
          fill={colors.chip}
        />
        <g fill={colors.dots}>
          {PRIMARY_CHIP.dots.map(({ cx, cy }) => (
            <circle key={`${cx}-${cy}`} cx={cx} cy={cy} r={PRIMARY_CHIP.dotR} />
          ))}
        </g>
        <circle
          cx={PRIMARY_CHIP.keeper.cx}
          cy={PRIMARY_CHIP.keeper.cy}
          r={PRIMARY_CHIP.keeper.r}
          fill={colors.keeper}
        />
      </g>
      <g fill={colors.word}>
        {LOCKUP_GLYPHS.map((g, i) => (
          <path
            key={i}
            transform={`translate(${g.x} ${g.y}) scale(${g.sx} ${g.sy})`}
            d={g.d}
          />
        ))}
      </g>
    </svg>
  )
}

/** 512 box, reduced tier: three over two with the keeper. */
export function EmailMark({
  colors,
  size,
}: {
  colors: { chip: string; dots: string; keeper: string }
  size: number
}) {
  return (
    <svg
      width={size}
      height={size}
      viewBox={`0 0 ${REDUCED_CHIP.size} ${REDUCED_CHIP.size}`}
      aria-hidden
      style={{ display: "block" }}
    >
      <rect
        width={REDUCED_CHIP.size}
        height={REDUCED_CHIP.size}
        rx={REDUCED_CHIP.rx}
        fill={colors.chip}
      />
      <g fill={colors.dots}>
        {REDUCED_CHIP.dots.map(({ cx, cy }) => (
          <circle key={`${cx}-${cy}`} cx={cx} cy={cy} r={REDUCED_CHIP.dotR} />
        ))}
      </g>
      <circle
        cx={REDUCED_CHIP.keeper.cx}
        cy={REDUCED_CHIP.keeper.cy}
        r={REDUCED_CHIP.keeper.r}
        fill={colors.keeper}
      />
    </svg>
  )
}
